import type { ImgHTMLAttributes } from "react";
import manifest from "@/data/imageManifest.json";

type Entry = { base: string; widths: number[]; ratio: number };

type Props = Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "srcSet"> & {
  src: string;
  /** How wide the image renders at each breakpoint, e.g. "(min-width: 1024px) 50vw, 100vw" */
  sizes: string;
};

// Serves AVIF/WebP variants generated by `npm run optimize:images`, falling back to the original file
const ResponsiveImage = ({ src, sizes, alt = "", loading = "lazy", ...rest }: Props) => {
  const entry = (manifest as Record<string, Entry>)[src];

  if (!entry) {
    return <img src={src} alt={alt} loading={loading} decoding="async" {...rest} />;
  }

  const srcSet = (ext: string) => entry.widths.map((w) => `${entry.base}-${w}.${ext} ${w}w`).join(", ");
  const largest = entry.widths[entry.widths.length - 1];

  return (
    <picture>
      <source type="image/avif" srcSet={srcSet("avif")} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet("webp")} sizes={sizes} />
      <img
        src={`${entry.base}-${largest}.webp`}
        alt={alt}
        width={largest}
        height={Math.round(largest * entry.ratio)}
        loading={loading}
        decoding="async"
        {...rest}
      />
    </picture>
  );
};

export default ResponsiveImage;
